<h1>Nueva orden</h1><form class="panel form" method="post" action="<?=BASE_URL?>/ordenes/save"><label>Equipo<select name="id_equipo" required><?php foreach($opt['equipos'] as $x):?><option value="<?=$x['id_equipo']?>"><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Técnico<select name="id_tecnico" required><?php foreach($opt['tecnicos'] as $x):?><option value="<?=$x['id_tecnico']?>"><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Estado<select name="id_estado"><?php foreach($opt['estados'] as $x):?><option value="<?=$x['id_estado']?>"><?=$x['nombre_estado']?></option><?php endforeach;?></select></label><label>Tipo<select name="tipo_mantenimiento"><option>Preventivo</option><option>Correctivo</option></select></label><label>Prioridad<select name="prioridad"><option>Baja</option><option>Media</option><option>Alta</option><option>Crítica</option></select></label><label>Fecha programada<input type="date" name="fecha_programada"></label><label>Falla<textarea name="descripcion_falla" required></textarea></label><label>Mano de obra<input type="number" min="0" step="0.01" name="costo_mano_obra" value="0"></label><button class="btn">Crear orden</button></form>

